import React, { useRef, useState } from 'react';
import './ImageLinkForm.css';

const ImageLinkForm = ({ onInputChange, onButtononSubmit, onFileChange }) => {
	const fileInputRef = useRef(null);
	const [mode, setMode] = useState('url'); // 'url' or 'browse'

	const handleBrowseClick = () => {
		fileInputRef.current.click();
	};

	return (
		<div>
			<p className='f3 white'>
				{'This Magic Brain will detect faces in your pictures. Give it a Try!'}
			</p>

			{/* Mode Toggle */}
			<div className='center mb3'>
				<div className='mode-toggle'>
					<button
						className={`mode-btn ${mode === 'url' ? 'mode-active' : ''}`}
						onClick={() => setMode('url')}
					>
						{/* Link Icon */}
						<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
							<path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/>
							<path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/>
						</svg>
						<span>Paste Link</span>
					</button>
					<button
						className={`mode-btn ${mode === 'browse' ? 'mode-active' : ''}`}
						onClick={() => setMode('browse')}
					>
						{/* Upload Icon */}
						<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
							<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
							<polyline points="17 8 12 3 7 8"/>
							<line x1="12" y1="3" x2="12" y2="15"/>
						</svg>
						<span>Browse File</span>
					</button>
				</div>
			</div>

			<div className='center'>
				{mode === 'url' ? (
					<div className='form center pa4 br3 shadow-5'>
						<input
							className='f4 pa2 w-70 center input-url'
							type='text'
							placeholder='Paste image URL here...'
							onChange={onInputChange}
						/>
						<button
							className='w-30 grow f4 link ph3 pv2 dib white bg-light-purple detect-btn'
							onClick={onButtononSubmit}
						>Detect</button>
					</div>
				) : (
					<div className='upload-area br3 shadow-5' onClick={handleBrowseClick}>
						<div className='upload-icon'>
							<svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
								<rect x="3" y="3" width="18" height="18" rx="2" ry="2"/>
								<circle cx="8.5" cy="8.5" r="1.5"/>
								<polyline points="21 15 16 10 5 21"/>
							</svg>
						</div>
						<p className='f4 mt2 mb0'>Click to browse or drag an image</p>
						<p className='f6 gray mt1'>Supports JPG, PNG, WEBP</p>
					</div>
				)}
				<input
					ref={fileInputRef}
					type='file'
					accept='image/*'
					style={{ display: 'none' }}
					onChange={onFileChange}
				/>
			</div>
		</div>
	);
}

export default ImageLinkForm;
